package com.moscilez.track;

import android.Manifest; import android.content.*; import android.content.pm.PackageManager; import android.graphics.Color; import android.os.*; import android.view.*; import android.widget.*;
import androidx.appcompat.app.AppCompatActivity; import androidx.core.app.ActivityCompat; import com.google.android.material.button.MaterialButton; import com.moscilez.track.data.*; import com.moscilez.track.tracking.TrackingService; import java.util.*;

public class MainActivity extends AppCompatActivity {
 private LinearLayout root, content; private MTrackDatabase db; private TextView title; private static final int LOCATION=42; private String pendingMode;
 @Override public void onCreate(Bundle b){super.onCreate(b); db=MTrackDatabase.get(this); showDashboard();}
 private TextView text(String s,int size){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(Color.rgb(20,20,20));v.setPadding(0,10,0,10);return v;}
 private MaterialButton button(String s){MaterialButton b=new MaterialButton(this);b.setText(s);b.setTextSize(14);b.setAllCaps(false);return b;}
 private void shell(String heading){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(32,32,32,20);root.setBackgroundColor(Color.rgb(250,250,247)); title=text(heading,30); title.setTypeface(null,1); root.addView(title); content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL); ScrollView scroll=new ScrollView(this);scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1)); LinearLayout nav=new LinearLayout(this);String[] labels={"Dashboard","History","Profile"};for(String l:labels){MaterialButton n=button(l);nav.addView(n,new LinearLayout.LayoutParams(0,56,1));if(l.equals("Dashboard"))n.setOnClickListener(v->showDashboard());if(l.equals("History"))n.setOnClickListener(v->showHistory());if(l.equals("Profile"))n.setOnClickListener(v->showProfile());}root.addView(nav);setContentView(root);}
 private void showDashboard(){shell("MTrack / Dashboard");content.addView(text("LOCAL MOVEMENT TRACKER",12));content.addView(text("Your activity, stored on this device.",18));MaterialButton start=button("START ACTIVITY");content.addView(start);start.setOnClickListener(v->startActivityPicker());content.addView(text("TODAY",12));content.addView(text("No activity recorded yet",22));content.addView(text("WEEK / 0 km / 0 sessions",16));}
 private void startActivityPicker(){shell("Start activity");content.addView(text("Choose a mode",18));String[] modes={"Run","Walk","Cycling","Car","Motorcycle","Scooter","Hike","Other"};for(String mode:modes){MaterialButton b=button(mode);content.addView(b);b.setOnClickListener(v->begin(mode));}}
 private void begin(String mode){if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED&&checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED){pendingMode=mode;ActivityCompat.requestPermissions(this,new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},LOCATION);return;}Intent i=new Intent(this,TrackingService.class);i.putExtra("mode",mode);try{startForegroundService(i);showTracking(mode);}catch(SecurityException e){Toast.makeText(this,"Location permission is required",Toast.LENGTH_LONG).show();}}
 @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] grants){super.onRequestPermissionsResult(code,permissions,grants);if(code==LOCATION&&pendingMode!=null){String mode=pendingMode;pendingMode=null;if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED)begin(mode);else Toast.makeText(this,"Location permission is required to record a route",Toast.LENGTH_LONG).show();}}
 private void showTracking(String mode){shell("Recording / "+mode);content.addView(text("GPS tracking is active",20));content.addView(text("00:00:00\n0.00 km\nWaiting for location…",32));MaterialButton stop=button("END ACTIVITY");content.addView(stop);stop.setOnClickListener(v->{stopService(new Intent(this,TrackingService.class));showDashboard();});}
 private void showHistory(){shell("MTrack / History");MaterialButton export=button("EXPORT LOCAL CSV");content.addView(export);export.setOnClickListener(v->{try{Toast.makeText(this,"Saved: "+LocalExport.write(this,db).getName(),Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(this,"Export failed",Toast.LENGTH_SHORT).show();}});List<ActivitySession> rows=db.sessions().all();if(rows.isEmpty()){content.addView(text("No activities yet",20));return;}for(ActivitySession s:rows){TextView row=text(s.type+"\n"+new Date(s.startedAt)+"   "+String.format(Locale.US,"%.2f km",s.distanceMeters/1000),17);content.addView(row);row.setOnClickListener(v->showDetails(s));}}
 private void showDetails(ActivitySession s){shell("Activity / "+s.type);content.addView(text(new Date(s.startedAt).toString(),15));content.addView(text(String.format(Locale.US,"%.2f km\nAvg %.1f km/h\nMax %.1f km/h\nDuration %d min",s.distanceMeters/1000,s.avgSpeed,s.maxSpeed,s.durationMs/60000),28));content.addView(text("GPS points: "+db.points().forSession(s.id).size(),16));MaterialButton delete=button("DELETE ACTIVITY");content.addView(delete);delete.setOnClickListener(v->{db.points().deleteForSession(s.id);db.sessions().delete(s);showHistory();});}
 private void showProfile(){shell("MTrack / Profile");content.addView(text("LOCAL PROFILE",12));EditText name=new EditText(this);name.setHint("Name or alias");content.addView(name);MaterialButton save=button("SAVE PROFILE");content.addView(save);save.setOnClickListener(v->{UserProfile p=new UserProfile();p.name=name.getText().toString();db.profiles().save(p);Toast.makeText(this,"Profile saved locally",Toast.LENGTH_SHORT).show();});}
}
